  const url = prefix + path

  opts.url = url
  opts.path = url
  opts.routePath = path
  opts.prefix = prefix
  opts.logLevel = opts.logLevel || this[kLogLevel]
  validateLogLevelOption(opts.logLevel, opts.method, opts.url, logger)

